discrete VoltageRegulator
port:
    event input real M;  // Activate Signal
event input real N;  // Close Command
event output real FaultDetected;  // Fault detection signal.
state:
    initial state state1  // Standby Mode
when entry() then
            statehold(0);  // Initialize to keep time as0
        end;
        when receive(M) then
            transition(state2);
        end;
        when receive(N) then
            transition(state1);
        end;
    end;

    state state2  // Normal working mode
when entry() then
            statehold(0);  // Initialize to keep time as0
        end;
        when receive(N) then
            transition(state1);
        end;
        when timeover() then
            transition(state1);
        end;
    end;

    state state3  // Fault protection mode
when entry() then
            statehold(0);  // Initialize to keep time as0
        end;
        when receive(N) then
            transition(state1);
        end;
        when timeover() then
            transition(state1);
        end;
    end;
end;
end;

discrete BoostConverter
port:
    event input real O;  // Start the signal.
event input real P;  // Disable signal
event input real ManualReset;  // Revert Manually
event output real OverloadDetected;  // Overload or malfunction
state:
    initial state state1  // Do not perform any lifting operations
when entry() then
            statehold(0);  // Initialize to keep time as0
        end;
        when receive(O) then
            transition(state2);
        end;
        when receive(P) then
            transition(state1);
        end;
    end;

    state state2  // Activate and maintain the target output voltage level required
when entry() then
            statehold(0);  // Initialize to keep time as0
        end;
        when receive(ManualReset) then
            transition(state1);
        end;
    end;

    state state3  // Overload Protection
when entry() then
            statehold(0);  // Initialize to keep time as0
        end;
        when receive(ManualReset) then
            transition(state1);
        end;
    end;
end;
end;

discrete BuckConverter
port:
    event input real Q;  // Activate Request
event input real R;  // Stop Command
event input real UnlockConfirm;  // Unlock confirmation.
event output real AbnormalCondition;  // Anomalous signal.
state:
    initial state state1  // No activity
when entry() then
            statehold(0);  // Initialize to keep time as0
        end;
        when receive(Q) then
            transition(state2);
        end;
        when receive(R) then
            transition(state1);
        end;
    end;

    state state2  // Adjust output below input voltage
when entry() then
            statehold(0);  // Initialize to keep time as0
        end;
        when receive(R) then
            transition(state1);
        end;
        when receive(UnlockConfirm) then
            transition(state2);
        end;
    end;

    state state3  // Secure Lock Status
when entry() then
            statehold(0);  // Initialize to keep time as0
        end;
        when receive(R) then
            transition(state1);
        end;
        when receive(UnlockConfirm) then
            transition(state2);
        end;
    end;
end;
end;

couple PowerManagementSystem
import architectureModels.VoltageRegulator as VR;
import architectureModels.BoostConverter as BC;
import architectureModels.BuckConverter as BK;
part:
    VR vrInstance;
    BC bcInstance;
    BK bkInstance;
connection:
    connect(vrInstance.OutputVoltage, bcInstance.InputVoltage);
    connect(vrInstance.OutputCurrent, bcInstance.InputCurrent);
    connect(vrInstance.OutputFault, bkInstance.InputFault);

    connect(bcInstance.OutputRegulated, bkInstance.InputRegulated);
    connect(bcInstance.OutputFeedback, bkInstance.InputFeedback);
    connect(bcInstance.OutputReset, vrInstance.InputReset);
    connect(bcInstance.OutputOverload, vrInstance.InputOverload);

    connect(bkInstance.OutputStatus, vrInstance.InputStatus);
    connect(bkInstance.OutputMonitor, vrInstance.InputMonitor);
    connect(bkInstance.OutputUnlock, bcInstance.InputUnlock);
    connect(bkInstance.OutputAbnormal, bcInstance.InputAbnormal);
end;
